public class Main {
    public static void main(String[] args) {
        String a = "hello";
        String b = null;
        System.out.println(Objects.nonNull(a));
        System.out.println(Objects.isNull(b));
        System.out.println(Objects.requireNonNullElse(b, "world"));
    }
}

